    if rest:
        walk(rest, board.copy(), "main", 0)
    for i, ch in enumerate(children):
        walk(ch, board.copy(), f"v{i}", 0)
    # count RIGHT
    rights = len(re.findall(r'RIGHT', text))
    print(f"RIGHT markers: {rights}")

if __name__ == '__main__':
    for p in sys.argv[1:]:
        main(p)

