        lines=[]
        for y in range(ymin, ymax+1):
            row=[]
            for x in range(xmin, xmax+1):
                v = self.get(x,y)
                row.append('.' if v is None else ('X' if v=='B' else 'O'))
            lines.append(f"{COLS[y]} " + " ".join(row))
        lines.append("  " + " ".join(COLS[x] for x in range(xmin,xmax+1)))
        return "\n".join(lines)

def make(ab, aw, region=(0,8,0,8)):
    b = Board()
    b.place('B', ab)
    b.place('W', aw)
    print(b.show(*region))
    print("--- groups ---")
    for c,n,l,pts,lpts in b.status():
        if n > 0 and any(COLS.index(p[0])<=region[1] and COLS.index(p[1])<=region[3] for p in pts):
            print(f"{c}: {n} stones, {l} libs: stones={pts} libs={lpts}")
    return b

# ========== Problem designs ==========

print("="*40, "P1 easy B kills")
# Bottom side: White has false eye shape, Black kills with one move
# Region around d-h, q-s
# 
#    d e f g h i
# q  X X X X X .
# r  X O O O X .
# s  . O . O X .
#
# White O group has libs: ds, fs, and maybe er area - er is O's? er not in white.
# White: er, fr, gr, es, gs
# Black: dq, eq, fq, gq, hq, dr, hr, hs, ir?
ab1 = ['dq','eq','fq','gq','hq','dr','hr','hs']
aw1 = ['er','fr','gr','es','gs']
b = make(ab1, aw1, (3,9,15,18))
# White libs should include ds, fs, maybe eq filled
# Black plays fs? or ds?
print("Try B[fs]")
b2=b; 
from copy import deepcopy
# manual
b = make(ab1, aw1, (3,9,15,18))
try:
    print("cap", b.play('B','fs'))
    print(b.show(3,9,15,18))
    for c,n,l,pts,lpts in b.status():
        if 'e' in ''.join(pts) or 'f' in ''.join(pts) or 'g' in ''.join(pts):
