#!/usr/bin/env python3
"""Interactive board designer helpers."""
COLS = "abcdefghijklmnopqrs"

def parse_pts(s):
    """'B:aa,ab W:ba,ca' or lists"""
    return s

class Board:
    def __init__(self):
        self.g = [[None]*19 for _ in range(19)]

    def place(self, color, pts):
        for p in pts:
            x, y = COLS.index(p[0]), COLS.index(p[1])
            if self.g[y][x] is not None:
                raise ValueError(f"overlap {p}")
            self.g[y][x] = color

    def get(self, x, y):
        return self.g[y][x]

    def neighbors(self, x, y):
        for dx, dy in ((0,1),(0,-1),(1,0),(-1,0)):
            nx, ny = x+dx, y+dy
            if 0 <= nx < 19 and 0 <= ny < 19:
                yield nx, ny

    def group(self, x, y):
        c = self.get(x, y)
        if c is None:
            return set(), set()
        stones, libs = set(), set()
        stack = [(x,y)]; seen=set()
        while stack:
            sx,sy = stack.pop()
            if (sx,sy) in seen: continue
            seen.add((sx,sy)); stones.add((sx,sy))
            for nx,ny in self.neighbors(sx,sy):
                v = self.get(nx,ny)
                if v is None: libs.add((nx,ny))
                elif v == c and (nx,ny) not in seen: stack.append((nx,ny))
        return stones, libs

    def play(self, color, pt):
        x, y = COLS.index(pt[0]), COLS.index(pt[1])
        if self.get(x,y) is not None:
            raise ValueError(f"occupied {pt}")
        self.g[y][x] = color
        opp = 'W' if color=='B' else 'B'
        captured = []
        for nx,ny in self.neighbors(x,y):
            if self.get(nx,ny)==opp:
                stones, libs = self.group(nx,ny)
                if not libs:
                    for sx,sy in stones:
                        self.g[sy][sx] = None
                        captured.append(COLS[sx]+COLS[sy])
        stones, libs = self.group(x,y)
        if not libs:
            raise ValueError(f"suicide {pt}")
        return captured

    def status(self):
        """Report groups and liberty counts."""
        seen=set(); out=[]
        for y in range(19):
            for x in range(19):
                if (x,y) in seen: continue
                c = self.get(x,y)
                if c is None: continue
                stones, libs = self.group(x,y)
                seen |= stones
                pts = sorted(COLS[sx]+COLS[sy] for sx,sy in stones)
                lpts = sorted(COLS[lx]+COLS[ly] for lx,ly in libs)
                out.append((c, len(stones), len(libs), pts, lpts))
        return out

    def show(self, xmin=0, xmax=10, ymin=0, ymax=10):
        lines=[]
        for y in range(ymin, ymax+1):
            row=[]
            for x in range(xmin, xmax+1):
                v = self.get(x,y)
                row.append('.' if v is None else ('X' if v=='B' else 'O'))
            lines.append(f"{COLS[y]} " + " ".join(row))
        lines.append("  " + " ".join(COLS[x] for x in range(xmin,xmax+1)))
        return "\n".join(lines)

def make(ab, aw, region=(0,8,0,8)):
    b = Board()
    b.place('B', ab)
    b.place('W', aw)
    print(b.show(*region))
    print("--- groups ---")
    for c,n,l,pts,lpts in b.status():
        if n > 0 and any(COLS.index(p[0])<=region[1] and COLS.index(p[1])<=region[3] for p in pts):
            print(f"{c}: {n} stones, {l} libs: stones={pts} libs={lpts}")
    return b

# ========== Problem designs ==========

print("="*40, "P1 easy B kills")
# Bottom side: White has false eye shape, Black kills with one move
